# Plain-language names used in AI prompts (the model understands both)
AI_LANGUAGE_NAME = {k: f'{v["english"]} ({v["native"]})' if k != "en" else "English" for k, v in LANGUAGES.items()}


# ─────────────────────────────────────────────
# STATIC TRANSLATIONS
# ─────────────────────────────────────────────
def cur_lang():
    return st.session_state.get("lang", "en")


def t_lang(_key, _lang, **kw):
    """Parameter names start with _ so any placeholder name (key=, lang=, ...) can be passed in **kw."""
    row = STRINGS.get(_key)
    if row is None:
        # Never show a raw key like "nav_home" on screen: fall back to readable English.
        text = _key.split("_", 1)[1] if _key.startswith("nav_") and "_" in _key else _key
        text = text.replace("_", " ").capitalize()
    else:
        text = row[LANG_ORDER.index(_lang)] if _lang in LANG_ORDER else row[0]
        text = text or row[0]
    return text.format(**kw) if kw else text


def t(_key, **kw):
    return t_lang(_key, cur_lang(), **kw)


def t_class(name, lang=None):
    """Trained-model class name in the current language."""
    key = f"cls_{name}"
    return t_lang(key, lang or cur_lang()) if key in STRINGS else name


def t_urgency(level, lang=None):
    key = f"urg_{str(level).lower()}"
    return t_lang(key, lang or cur_lang()) if key in STRINGS else str(level)


# ─────────────────────────────────────────────
# AI TRANSLATION WITH DATABASE CACHE
# ─────────────────────────────────────────────
SEEN = set()                       # every English string passed to tr() in this server process
PLACEHOLDER_RE = re.compile(r"\{[a-z_]+\}")
TAG_RE = re.compile(r"</?[a-zA-Z][^>]*>")


def _session_cache(lang):
    caches = st.session_state.setdefault("tr_cache", {})
    if lang not in caches:
        caches[lang] = {}
        loaded = st.session_state.setdefault("tr_loaded", set())
        if lang not in loaded:
            with db.connect() as conn:
                rows = conn.execute("SELECT src, text FROM translations WHERE lang = ?", (lang,)).fetchall()
            caches[lang].update({r["src"]: r["text"] for r in rows})
            loaded.add(lang)
    return caches[lang]


def tr(text):
    """Translate longer content. Returns English until the AI translation is ready (then the page reruns)."""
    if not text or not isinstance(text, str):
        return text
    lang = cur_lang()
    if lang == "en":
        return text
    SEEN.add(text)
    cache = _session_cache(lang)
    if text in cache:
        return cache[text]
    st.session_state.setdefault("tr_pending", set()).add(text)
    return text


def tr_list(items):
    return [tr(x) for x in items]


def _valid(src, dst):
    if not dst or not isinstance(dst, str):
        return False
    if set(PLACEHOLDER_RE.findall(src)) != set(PLACEHOLDER_RE.findall(dst)):
        return False
    if len(TAG_RE.findall(src)) != len(TAG_RE.findall(dst)):
        return False
    return True


def translate_batch(texts, lang, api_key, preferred, chunk=25):
    """Translate English strings with the AI. Returns {english: translated} for the ones that came back valid."""
    target = AI_LANGUAGE_NAME[lang]
    done = {}
    for i in range(0, len(texts), chunk):
        part = texts[i:i + chunk]
        payload = {str(n + 1): s for n, s in enumerate(part)}
        prompt = (
            f"Translate every value in this JSON object from English into {target} for a dermatology health app "
            "used by ordinary people. Use simple, natural, everyday language. Keep the same keys. "
            "Keep emojis, numbers, %, units, punctuation, {placeholders}, HTML tags and markdown (**, -) exactly as they are. "
            "For medicine, ingredient and disease names, use the common local term if there is one, otherwise keep the "
            "English name (you may add the English in brackets). Reply with ONLY the JSON object.\n\n"
            + json.dumps(payload, ensure_ascii=False)
        )
        try:
            raw = ask_ai_text([{"role": "user", "content": prompt}], api_key, preferred, max_tokens=4000)
            out = parse_json(raw)
        except Exception:
            continue
        for k, src in payload.items():
            dst = out.get(k) if isinstance(out, dict) else None
            if _valid(src, dst):
                done[src] = dst.strip()
    return done


def flush_translations(api_key, preferred):
    """Call once at the end of every page render."""
    lang = cur_lang()
    pending = st.session_state.pop("tr_pending", set())
    if lang == "en" or not pending:
        return
    attempted = st.session_state.setdefault("tr_attempted", {}).setdefault(lang, set())
    todo = [p for p in pending if p not in attempted]
    if not todo:
        if pending - set(_session_cache(lang)):
            st.caption("🌐 " + (t("translate_need_key") if not api_key else t("translate_failed")))
        return
    cache = _session_cache(lang)

    # someone else may already have translated these
    found = db.get_translations(lang, todo)
    cache.update(found)
    todo = [x for x in todo if x not in found]
    if not todo:
        st.rerun()

    if not api_key:
        attempted.update(todo)
        st.caption("🌐 " + t("translate_need_key"))
        return

    with st.spinner("🌐 " + t("translating", lang=LANGUAGES[lang]["native"])):
        done = translate_batch(todo, lang, api_key, preferred)
    attempted.update(todo)
    if done:
        db.put_translations(lang, done)
        cache.update(done)
    if done or found:
        st.rerun()
    st.caption("🌐 " + t("translate_failed"))


def pretranslate_all(texts, api_key, preferred, progress=None):
    """Admin tool: translate a list of English strings into every language and store them."""
    total = 0
    langs = [l for l in LANG_ORDER if l != "en"]
    for n, lang in enumerate(langs):
        have = db.get_translations(lang, texts)
        todo = [x for x in texts if x not in have]
        if todo:
            done = translate_batch(todo, lang, api_key, preferred)
            if done:
                db.put_translations(lang, done)
                total += len(done)
        if progress:
            progress((n + 1) / len(langs), LANGUAGES[lang]["native"])
    st.session_state.pop("tr_cache", None)
    st.session_state.pop("tr_loaded", None)
    st.session_state.pop("tr_attempted", None)
    return total
